app.post('/api/register',async(req,res)=>{
 const name=String(req.body.name||'').trim();
 const p=phone(req.body.phone);
 const pw=String(req.body.password||'');
 if(!name||!p||pw.length<6)return res.status(400).json({error:'Nom, numéro et mot de passe (6 caractères minimum) requis.'});
 try{
  const h=await bcrypt.hash(pw,12);
  const r=db.prepare('INSERT INTO users(name,phone,password_hash) VALUES(?,?,?)').run(name,p,h);
  req.session.userId=r.lastInsertRowid;
  res.json({ok:true,user:{id:r.lastInsertRowid,name,phone:p}});
 }catch(e){res.status(409).json({error:'Ce numéro est déjà inscrit.'});}
});

app.post('/api/login',async(req,res)=>{
 const p=phone(req.body.phone),pw=String(req.body.password||'');
 const u=db.prepare('SELECT * FROM users WHERE phone=?').get(p);
 if(!u||!(await bcrypt.compare(pw,u.password_hash)))return res.status(401).json({error:'Numéro ou mot de passe incorrect.'});
 req.session.userId=u.id;
 res.json({ok:true,user:{id:u.id,name:u.name,phone:u.phone}});
});

app.post('/api/logout',(req,res)=>req.session.destroy(()=>res.json({ok:true})));
app.get('/api/me',auth,(req,res)=>{
 const u=db.prepare('SELECT id,name,phone,created_at FROM users WHERE id=?').get(req.session.userId);
 res.json({user:u});
});
app.post('/api/analyses',auth,(req,res)=>{
 const o=Number(req.body.oddsType);
 if(![2,10].includes(o))return res.status(400).json({error:'Type invalide.'});
 const r=db.prepare("INSERT INTO analyses(user_id,odds_type,status) VALUES(?,?, 'payment_pending')").run(req.session.userId,o);
 res.json({ok:true,id:r.lastInsertRowid,oddsType:o});
});
app.get('/api/analyses',auth,(req,res)=>res.json({analyses:db.prepare('SELECT id,odds_type,status,created_at FROM analyses WHERE user_id=? ORDER BY id DESC').all(req.session.userId)}));

app.post('/api/admin/login',(req,res)=>{
 const u=String(req.body.username||''),p=String(req.body.password||'');
 if(u!==(process.env.ADMIN_USERNAME||'owner')||p!==(process.env.ADMIN_PASSWORD||'CHANGE-ME'))return res.status(401).json({error:'Identifiants administrateur incorrects.'});
 req.session.admin=true;res.json({ok:true});
});
app.post('/api/admin/logout',(req,res)=>{req.session.admin=false;res.json({ok:true});});
app.get('/api/admin/status',(req,res)=>res.json({authenticated:Boolean(req.session.admin)}));
app.get('/api/admin/users',admin,(req,res)=>res.json({users:db.prepare('SELECT id,name,phone,created_at FROM users ORDER BY id DESC').all()}));
app.delete('/api/admin/users/:id',admin,(req,res)=>{
 const id=Number(req.params.id);
 db.transaction(()=>{db.prepare('DELETE FROM analyses WHERE user_id=?').run(id);db.prepare('DELETE FROM users WHERE id=?').run(id)})();
 res.json({ok:true});
});

app.listen(PORT,()=>console.log('S-Drive sur le port '+PORT));
